import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { getUser, logout } from "../utils/auth";

function Navbar() {
  const [user, setUser] = useState(null);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    setUser(getUser());
  }, []);

  const handleLogout = () => {
    logout();
    setUser(null);
    window.location.reload();
  };

  return (
    <nav style={styles.nav}>
      <h2 style={styles.logo}>DocBook</h2>

      <div style={styles.links}>
        <Link to="/">Doctors</Link>
        <Link to="/appointments">My Appointments</Link>
      </div>

      {/* Right Section */}
      <div style={{ position: "relative" }}>
        {user ? (
          <>
            {/* Profile Image */}
            <img
              src="https://randomuser.me/api/portraits/men/75.jpg"
              alt="profile"
              style={styles.avatar}
              onClick={() => setOpen(!open)}
            />

            {/* Dropdown */}
            {open && (
              <div style={styles.dropdown}>
                <p style={styles.dropdownItem}>
                  👤 {user.name}
                </p>

                <Link to="/appointments" style={styles.dropdownItem}>
                  📅 My Appointments
                </Link>

                <p onClick={handleLogout} style={styles.dropdownItem}>
                  🚪 Logout
                </p>
              </div>
            )}
          </>
        ) : (
          <Link to="/login" style={styles.loginBtn}>
            Login
          </Link>
        )}
      </div>
    </nav>
  );
}

const styles = {
nav: {
  display: "flex",
  justifyContent: "space-between",
  padding: "15px 30px",
  background: "#fff",
  boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
  alignItems: "center",
  position: "relative",  // ⭐ add this
  zIndex: 1000,          // ⭐ ensures navbar is above page
},
  logo: {
    color: "#1976d2",
  },
  links: {
    display: "flex",
    gap: "20px",
  },
  loginBtn: {
    padding: "6px 14px",
    background: "#1976d2",
    color: "#fff",
    borderRadius: "5px",
    textDecoration: "none",
  },
  avatar: {
    width: "40px",
    height: "40px",
    borderRadius: "50%",
    cursor: "pointer",
    border: "2px solid #1976d2",
  },
 dropdown: {
  position: "absolute",
  right: "0",
  top: "50px",
  background: "#fff",
  borderRadius: "8px",
  boxShadow: "0 4px 12px rgba(0,0,0,0.15)",
  width: "180px",
  padding: "10px",
  zIndex: 9999,   // ⭐ VERY IMPORTANT
},
  dropdownItem: {
    padding: "8px",
    cursor: "pointer",
    borderRadius: "5px",
    textDecoration: "none",
    color: "#333",
  },
};

export default Navbar;
